import json

# Diagonal bands - same value on each diagonal (row - col = constant mod 7)
grid = []
for row in range(7):
    for col in range(4):
        diag = (row - col) % 7
        grid.append([diag for _ in range(4)])

submit = {"action": "submit", "grid": grid}
print(json.dumps(submit))

import json

# Diagonal bands - same value on each anti-diagonal (row + col = constant)
grid = []
for row in range(7):
    grid.append([])
    for col in range(4):
        diag = (row + col) % 7
        grid[row].append(diag)

submit = {"action": "submit", "grid": grid}
print(json.dumps(submit))
